import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String[] lines = new String(System.in.readAllBytes()).split("\r?\n", -1);
        String s = Long.parseLong(lines[0].trim()) != 0 ? lines[1] : "";
        // Each boundary between two runs contributes min(previous run, current run).
        long previous = 0, current = 0, answer = 0;
        char last = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == last) current++;
            else {
                answer += Math.min(previous, current);
                previous = current;
                current = 1;
                last = c;
            }
        }
        System.out.println(answer + Math.min(previous, current));
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	raw, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	lines := strings.Split(string(raw), "\n")
	s := ""
	if strings.TrimSpace(lines[0]) != "0" {
		s = strings.TrimSuffix(lines[1], "\r")
	}
	// Each boundary between two runs contributes min(previous run, current run).
	var previous, current, answer int64
	var last byte
	for i := 0; i < len(s); i++ {
		if s[i] == last {
			current++
		} else {
			answer += min(previous, current)
			previous, current, last = current, 1, s[i]
		}
	}
	fmt.Println(answer + min(previous, current))
}
